package main

import (
	"errors"
	"fmt"

	"github.com/gin-gonic/gin"
)

type TestErr struct{ s string }

func (t TestErr) Error() string { return t.s }

func main() {
	innerErr := TestErr{"boom"}

	// value form
	errV := gin.Error{Err: innerErr, Type: gin.ErrorTypeAny}
	wrappedV := fmt.Errorf("wrapped: %w", errV)
	fmt.Println("value  errors.Is :", errors.Is(wrappedV, innerErr))
	var tv TestErr
	fmt.Println("value  errors.As :", errors.As(wrappedV, &tv))

	// pointer form
	errP := &gin.Error{Err: innerErr, Type: gin.ErrorTypeAny}
	wrappedP := fmt.Errorf("wrapped: %w", errP)
	fmt.Println("ptr    errors.Is :", errors.Is(wrappedP, innerErr))
	var tp TestErr
	fmt.Println("ptr    errors.As :", errors.As(wrappedP, &tp))

	// interface satisfaction checks
	var _ error = gin.Error{}
	var _ error = &gin.Error{}
	fmt.Printf("value implements interface{Unwrap() error}: %v\n", func() bool {
		_, ok := interface{}(errV).(interface{ Unwrap() error })
		return ok
	}())
	fmt.Printf("ptr   implements interface{Unwrap() error}: %v\n", func() bool {
		_, ok := interface{}(errP).(interface{ Unwrap() error })
		return ok
	}())
}
EOF
