package main

import (
	"errors"
	"fmt"

	"github.com/gin-gonic/gin"
)

type TestErr struct{ s string }

func (t TestErr) Error() string { return t.s }

func check(name string, got, want bool) {
	status := "OK "
	if got != want {
		status = "FAIL"
	}
	fmt.Printf("%s %-46s got=%v want=%v\n", status, name, got, want)
}

func main() {
	innerErr := TestErr{"boom"}
	innerStd := errors.New("std inner")

	// user snippet: value form
	errV := gin.Error{Err: innerErr, Type: gin.ErrorTypeAny}
	wrappedV := fmt.Errorf("wrapped: %w", errV)
	check("value errors.Is(wrapped, innerErr)", errors.Is(wrappedV, innerErr), true)
	var tv TestErr
	check("value errors.As(wrapped, &TestErr)", errors.As(wrappedV, &tv), true)

	// pointer form must keep working
	errP := &gin.Error{Err: innerErr, Type: gin.ErrorTypeAny}
	wrappedP := fmt.Errorf("wrapped: %w", errP)
	check("ptr errors.Is(wrapped, innerErr)", errors.Is(wrappedP, innerErr), true)
	var tp TestErr
	check("ptr errors.As(wrapped, &TestErr)", errors.As(wrappedP, &tp), true)

	// errors.Unwrap traversal
	check("value errors.Unwrap(wrapped) == errV", errors.Unwrap(wrappedV) == error(errV), true)
	check("value errors.Unwrap(errV) == innerErr", errors.Unwrap(errV) == error(innerErr), true)

	// errors.As into *gin.Error target
	var gev gin.Error
	check("value errors.As(wrapped, &gin.Error)", errors.As(wrappedV, &gev), true)
	var gep *gin.Error
	check("ptr errors.As(wrapped, &*gin.Error)", errors.As(wrappedP, &gep), true)

	// multi-layer wrapping, std sentinel, value form
	multi := fmt.Errorf("a: %w", fmt.Errorf("b: %w", gin.Error{Err: innerStd, Type: gin.ErrorTypeAny}))
	check("value multi-layer errors.Is(innerStd)", errors.Is(multi, innerStd), true)

	// interface satisfaction
	var _ error = gin.Error{}
	var _ error = &gin.Error{}
	_, vOK := interface{}(errV).(interface{ Unwrap() error })
	_, pOK := interface{}(errP).(interface{ Unwrap() error })
	check("gin.Error value implements Unwrap", vOK, true)
	check("*gin.Error implements Unwrap", pOK, true)

	// Error() string still fine for both forms
	check("value Error() string", errV.Error() == "boom", true)
	check("ptr Error() string", errP.Error() == "boom", true)
}
EOF
GOFLAGS=-mod=mod GOPROXY=off go run . 2>&1

