	gin.SetMode(gin.TestMode)

	// Case 1: user's sequence - late WriteHeader(401) after response sent must not change status
	r := gin.New()
	r.GET("/late", func(c *gin.Context) {
		c.Writer.WriteHeader(http.StatusOK)
		c.Writer.WriteHeaderNow()
		c.Writer.WriteHeader(http.StatusUnauthorized)
		fmt.Println("case1 Status() =", c.Writer.Status())
	})
	w := httptest.NewRecorder()
	r.ServeHTTP(w, httptest.NewRequest("GET", "/late", nil))
	fmt.Println("case1 client code =", w.Code)

	// Case 2: normal - WriteHeader(401) before anything written
	r2 := gin.New()
	r2.GET("/normal", func(c *gin.Context) {
		c.Writer.WriteHeader(http.StatusUnauthorized)
		fmt.Println("case2 Status() =", c.Writer.Status())
	})
	w2 := httptest.NewRecorder()
	r2.ServeHTTP(w2, httptest.NewRequest("GET", "/normal", nil))
	fmt.Println("case2 client code =", w2.Code)

	// Case 3: body written first, then late status change
	r3 := gin.New()
	r3.GET("/body", func(c *gin.Context) {
		c.String(http.StatusOK, "hello")
		c.Writer.WriteHeader(http.StatusUnauthorized)
		fmt.Println("case3 Status() =", c.Writer.Status())
	})
	w3 := httptest.NewRecorder()
	r3.ServeHTTP(w3, httptest.NewRequest("GET", "/body", nil))
	fmt.Println("case3 client code =", w3.Code, "body =", w3.Body.String())

	ok := true
	if w.Code != 200 {
		fmt.Println("FAIL: case1 client got", w.Code)
		ok = false
	}
	if w2.Code != 401 {
		fmt.Println("FAIL: case2 client got", w2.Code)
		ok = false
	}
	if w3.Code != 200 {
		fmt.Println("FAIL: case3 client got", w3.Code)
		ok = false
	}
	if ok {
		fmt.Println("ALL CLIENT CODES OK")
	}
}
