package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

func headerFor(filename string) string {
	w := httptest.NewRecorder()
	c, _ := gin.CreateTestContext(w)
	c.Request, _ = http.NewRequest("GET", "/", nil)
	c.FileAttachment("/gin/gin.go", filename)
	return w.Header().Get("Content-Disposition")
}

// parseFilename extracts the single filename parameter value from a
// Content-Disposition header, honoring quoted-string escaping.
func parseFilename(v string) (string, error) {
	const prefix = "attachment; filename="
	if !strings.HasPrefix(v, prefix) {
		return "", fmt.Errorf("unexpected prefix: %q", v)
	}
	rest := v[len(prefix):]
	if len(rest) == 0 || rest[0] != '"' {
		return "", fmt.Errorf("value not a quoted-string: %q", rest)
	}
	var sb strings.Builder
	i := 1
	for ; i < len(rest); i++ {
		ch := rest[i]
		if ch == '\\' {
			i++
			if i >= len(rest) {
				return "", fmt.Errorf("dangling escape")
			}
			sb.WriteByte(rest[i])
			continue
		}
		if ch == '"' {
			break
		}
		sb.WriteByte(ch)
	}
	if i >= len(rest) {
		return "", fmt.Errorf("unterminated quoted-string")
	}
	if rest[i+1:] != "" {
		return "", fmt.Errorf("trailing garbage after quoted-string: %q", rest[i+1:])
	}
	return sb.String(), nil
}

func check(name, filename, wantHeader, wantParsed string) {
	got := headerFor(filename)
	ok := got == wantHeader
	parsed, err := parseFilename(got)
	parseOK := err == nil && parsed == wantParsed
	fmt.Printf("%-14s filename=%q\n  header  = %q\n  expected= %q  -> %v\n  parsed filename = %q err=%v -> %v\n",
		name, filename, got, wantHeader, ok, parsed, err, parseOK)
	if !ok || !parseOK {
		fmt.Println("FAIL")
		return
	}
	fmt.Println("PASS")
}

func main() {
	check("normal", "report.pdf",
		`attachment; filename="report.pdf"`, "report.pdf")
	check("malicious", `evil"; dummy="x.sh`,
		`attachment; filename="evil\"; dummy=\"x.sh"`, `evil"; dummy="x.sh`)
	check("backslash", `dir\file.txt`,
		`attachment; filename="dir\\file.txt"`, `dir\file.txt`)
	check("mixed", `a\";b`,
		`attachment; filename="a\\\";b"`, `a\";b`)
}
